import { max, min } from 'd3-array';
import { pointRadial } from 'd3-shape';
import { notNull } from '@layerstack/utils';
import { accessor, chartDataArray, isEqualValue } from '../../utils/common.js';
import { isScaleBand, isScaleTime } from '../../utils/scales.svelte.js';
import { isSinglePointMode, panelDatum } from '../../utils/tooltip.js';
import { getChartContext } from '../../contexts/chart.js';
import { getFacetPanel } from '../../contexts/facet.js';
/**
 * Reactive state shared by every per-layer Highlight variant. Holds the
 * derived `lines`, `area`, and `points` arrays the template renders, plus
 * helpers like `axis` and `getPointRadius`.
 */
export class HighlightState {
    #getProps = () => ({});
    /**
     * Memoized props — the component's props closure allocates a fresh object
     * (it spreads `rest`), so calling it once per derived meant one allocation
     * per derived per update. Read it once here instead.
     */
    #props = $derived(this.#getProps());
    ctx = getChartContext();
    #facetPanel = getFacetPanel();
    constructor(getProps) {
        this.#getProps = getProps;
    }
    x = $derived(accessor(this.#props.x ?? this.ctx.x));
    y = $derived(accessor(this.#props.y ?? this.ctx.y));
    highlightData = $derived(this.#props.data ?? this.ctx.tooltip.data);
    /**
     * Whether the highlighted row belongs to the panel this is rendering into.
     *
     * Everything is confined to that panel unless `facetAll` asks for the hovered position to be
     * marked in all of them.
     */
    inPanel = $derived(this.#facetPanel?.().has(this.highlightData) ?? true);
    xValue = $derived(this.x(this.highlightData));
    xCoord = $derived(Array.isArray(this.xValue)
        ? this.xValue.map((v) => this.ctx.xScale(v))
        : this.ctx.xScale(this.xValue));
    xOffset = $derived(isScaleBand(this.ctx.xScale) && !this.ctx.radial ? this.ctx.xScale.bandwidth() / 2 : 0);
    xCoordScalar = $derived(Array.isArray(this.xCoord)
        ? (this.xCoord[0] + this.xCoord[this.xCoord.length - 1]) / 2
        : this.xCoord);
    yValue = $derived(this.y(this.highlightData));
    yCoord = $derived(Array.isArray(this.yValue)
        ? this.yValue.map((v) => this.ctx.yScale(v))
        : this.ctx.yScale(this.yValue));
    yOffset = $derived(isScaleBand(this.ctx.yScale) && !this.ctx.radial ? this.ctx.yScale.bandwidth() / 2 : 0);
    yCoordScalar = $derived(Array.isArray(this.yCoord)
        ? (this.yCoord[0] + this.yCoord[this.yCoord.length - 1]) / 2
        : this.yCoord);
    axis = $derived.by(() => {
        const axisProp = this.#props.axis;
        return axisProp == null
            ? isScaleBand(this.ctx.yScale) || isScaleTime(this.ctx.yScale) || this.ctx.valueAxis === 'x'
                ? 'y'
                : 'x'
            : axisProp;
    });
    /** Resolve radius for a data item using the chart's rScale */
    getPointRadius(d) {
        const rProp = this.#props.r;
        if (!rProp || !d)
            return undefined;
        if (rProp === true) {
            return this.ctx.config.r ? this.ctx.rGet(d) : undefined;
        }
        const value = accessor(rProp)(d);
        return value != null ? this.ctx.rScale(value) : undefined;
    }
    lines = $derived.by(() => {
        let tmpLines = [];
        if (!this.highlightData)
            return tmpLines;
        // The crosshair marks a position rather than a row, so `facetAll` draws it in every panel —
        // including ones with nothing there, which `points` skips
        if (!this.inPanel && !this.#props.facetAll)
            return tmpLines;
        const axis = this.axis;
        if (axis === 'x' || axis === 'both') {
            if (Array.isArray(this.xCoord)) {
                tmpLines = [
                    ...tmpLines,
                    ...this.xCoord.filter(notNull).map((xItem) => ({
                        x1: xItem + this.xOffset,
                        y1: min(this.ctx.yRange),
                        x2: xItem + this.xOffset,
                        y2: max(this.ctx.yRange),
                    })),
                ];
            }
            else if (this.xCoord != null) {
                tmpLines = [
                    ...tmpLines,
                    {
                        x1: this.xCoord + this.xOffset,
                        y1: min(this.ctx.yRange),
                        x2: this.xCoord + this.xOffset,
                        y2: max(this.ctx.yRange),
                    },
                ];
            }
        }
        if (axis === 'y' || axis === 'both') {
            if (Array.isArray(this.yCoord)) {
                tmpLines = [
                    ...tmpLines,
                    ...this.yCoord.filter(notNull).map((yItem) => ({
                        x1: min(this.ctx.xRange),
                        y1: yItem + this.yOffset,
                        x2: max(this.ctx.xRange),
                        y2: yItem + this.yOffset,
                    })),
                ];
            }
            else if (this.yCoord != null) {
                tmpLines = [
                    ...tmpLines,
                    {
                        x1: min(this.ctx.xRange),
                        y1: this.yCoord + this.yOffset,
                        x2: max(this.ctx.xRange),
                        y2: this.yCoord + this.yOffset,
                    },
                ];
            }
        }
        if (this.ctx.radial) {
            tmpLines = tmpLines.map((l) => {
                const [x1, y1] = pointRadial(l.x1, l.y1);
                const [x2, y2] = pointRadial(l.x2, l.y2);
                return { ...l, x1, y1, x2, y2 };
            });
        }
        return tmpLines;
    });
    area = $derived.by(() => {
        const tmpArea = { x: 0, y: 0, width: 0, height: 0 };
        if (!this.highlightData)
            return tmpArea;
        // The panel is the band when faceting groups a band scale, so the whole panel is marked
        // rather than the one bar the pointer landed on.  `inPanel` already keeps this to the
        // hovered panel.
        if (this.ctx.facetBand) {
            return {
                x: min(this.ctx.xRange),
                y: min(this.ctx.yRange),
                width: (max(this.ctx.xRange) - min(this.ctx.xRange)),
                height: (max(this.ctx.yRange) - min(this.ctx.yRange)),
            };
        }
        const axis = this.axis;
        if (axis === 'x' || axis === 'both') {
            if (Array.isArray(this.xCoord)) {
                tmpArea.x = min(this.xCoord);
                tmpArea.width = (max(this.xCoord) - min(this.xCoord));
            }
            else if (isScaleBand(this.ctx.xScale)) {
                tmpArea.x =
                    this.xCoord - (this.ctx.xScale.padding() * this.ctx.xScale.step()) / 2;
                tmpArea.width = this.ctx.xScale.step();
            }
            else if (this.ctx.xInterval) {
                const start = this.ctx.xInterval.floor(this.xValue);
                const end = this.ctx.xInterval.offset(start);
                const xStart = this.ctx.xScale(start);
                const xEnd = this.ctx.xScale(end);
                tmpArea.x = Math.min(xStart, xEnd);
                tmpArea.width = Math.abs(xEnd - xStart);
            }
            else {
                const index = this.ctx.flatData.findIndex((d) => Number(this.x(d)) === Number(this.x(this.highlightData)));
                const isLastPoint = index + 1 === this.ctx.flatData.length;
                const nextDataPoint = isLastPoint
                    ? max(this.ctx.xDomain)
                    : this.x(this.ctx.flatData[index + 1]);
                tmpArea.x = this.xCoord;
                tmpArea.width = (this.ctx.xScale(nextDataPoint) ?? 0) - (this.xCoord ?? 0);
            }
            if (axis === 'x') {
                tmpArea.y = min(this.ctx.yRange);
                tmpArea.height = (max(this.ctx.yRange) - min(this.ctx.yRange));
            }
        }
        if (axis === 'y' || axis === 'both') {
            if (Array.isArray(this.yCoord)) {
                tmpArea.y = min(this.yCoord);
                tmpArea.height = (max(this.yCoord) - min(this.yCoord));
            }
            else if (isScaleBand(this.ctx.yScale)) {
                tmpArea.y =
                    this.yCoord - (this.ctx.yScale.padding() * this.ctx.yScale.step()) / 2;
                tmpArea.height = this.ctx.yScale.step();
            }
            else if (this.ctx.yInterval) {
                const start = this.ctx.yInterval.floor(this.yValue);
                const end = this.ctx.yInterval.offset(start);
                const yStart = this.ctx.yScale(start);
                const yEnd = this.ctx.yScale(end);
                tmpArea.y = Math.min(yStart, yEnd);
                tmpArea.height = Math.abs(yEnd - yStart);
            }
            else {
                const index = this.ctx.flatData.findIndex((d) => Number(this.y(d)) === Number(this.y(this.highlightData)));
                const isLastPoint = index + 1 === this.ctx.flatData.length;
                const nextDataPoint = isLastPoint
                    ? max(this.ctx.yDomain)
                    : this.y(this.ctx.flatData[index + 1]);
                tmpArea.y = this.yCoord;
                tmpArea.height = (this.ctx.yScale(nextDataPoint) ?? 0) - (this.yCoord ?? 0);
            }
            if (axis === 'y') {
                tmpArea.width = max(this.ctx.xRange);
            }
        }
        return tmpArea;
    });
    /**
     * The colour for a point on `seriesInfo`'s series.
     *
     * A series carries its own colour, and that's what the point takes.  The exception is the
     * default series, which stands in for a chart that has none — there `c` is what colours the
     * marks, so a point taking the series colour would sit on a line of a different colour.  It's
     * the rule the `facetAll` copies and the series-less path already follow.
     */
    #pointFill(seriesInfo) {
        if (this.ctx.cChannel && this.ctx.series.isDefaultSeries) {
            return this.ctx.cGet(this.highlightData) ?? seriesInfo.color ?? '';
        }
        return seriesInfo.color ?? '';
    }
    /**
     * The row this panel marks when the hovered one belongs to another — `facetAll` only.
     *
     * Resolved by position rather than copied, so each panel shows *its* value there, and a panel
     * with no row at that position shows nothing.
     */
    #facetMatch = $derived.by(() => {
        const panel = this.#facetPanel?.();
        if (!this.#props.facetAll || !panel || !this.highlightData)
            return null;
        const match = panelDatum(this.ctx, panel, this.highlightData);
        if (match == null)
            return null;
        const x = this.x(match);
        const y = this.y(match);
        return {
            x: this.ctx.xScale(x) + this.xOffset,
            y: this.ctx.yScale(y) + this.yOffset,
            fill: (this.ctx.cChannel ? this.ctx.cGet(match) : null),
            data: { x, y },
            seriesKey: undefined,
        };
    });
    points = $derived.by(() => {
        let tmpPoints = [];
        if (!this.highlightData)
            return tmpPoints;
        if (!this.inPanel)
            return this.#facetMatch ? [this.#facetMatch] : tmpPoints;
        const props = this.#props;
        // Long data grouped by `c` draws a line per category from one implicit series, so the tooltip's
        // series list names only the row the pointer resolved to — one point, on whichever category
        // happened to be last.  Point every category at this position instead, as the tooltip lists
        // them.
        //
        // Only where the pointer resolved to a *position*, though.  `quadtree` and `voronoi` resolve
        // to one row by proximity in both axes — a scatter, where the rows sharing an x are unrelated
        // points rather than a category's line, and pointing all of them marks places nothing was
        // hovered.
        if (props.data === undefined &&
            this.ctx.cGroups &&
            this.ctx.series.isDefaultSeries &&
            !isSinglePointMode(this.ctx.tooltip.mode)) {
            const value = this.ctx.valueAxis === 'y' ? this.ctx.y : this.ctx.x;
            // Within a facet, only that panel's rows — the same category appears in every panel, and
            // pointing all of them would put the other panels' values in this one.  Outside one it's
            // `flatData`, which is what the tooltip resolves against and what the accessors are written
            // for: a chart whose `data` is nested (a `stack()`, say) passes its rows as `flatData`, and
            // iterating `data` there would hand the accessors a series rather than a row.
            const source = this.#facetPanel?.().data ?? chartDataArray(this.ctx.flatData);
            const rows = source.filter((d) => isEqualValue(this.x(d), this.xValue));
            // A multi-value accessor (`y={[0, 1]}`, as a stack's bands use) gives a category a span
            // rather than a position, so there is no single point to put on it.  Those belong to the
            // series path below, which points each of the values.
            const spans = rows.some((row) => Array.isArray(value(row)));
            // No visibility filter needed — rows of a `c` category the legend has hidden are already
            // gone from `ctx.data`, which is what keeps the scales in step with the legend
            if (!spans)
                return rows
                    .map((row) => {
                    const seriesValue = value(row);
                    return {
                        x: this.ctx.valueAxis === 'x'
                            ? this.ctx.xScale(seriesValue) + this.xOffset
                            : this.xCoordScalar + this.xOffset,
                        y: this.ctx.valueAxis === 'x'
                            ? this.yCoordScalar + this.yOffset
                            : this.ctx.yScale(seriesValue) + this.yOffset,
                        fill: this.ctx.cChannel ? this.ctx.cGet(row) : null,
                        data: { x: this.xValue, y: seriesValue },
                        seriesKey: this.ctx.cKey(row) ?? undefined,
                    };
                })
                    .filter(notNull);
        }
        if (props.data === undefined && this.ctx.tooltip.series.length > 0) {
            tmpPoints = this.ctx.tooltip.series
                .flatMap((seriesInfo) => {
                if (!seriesInfo.visible)
                    return [];
                let pointX;
                let pointY;
                let dataX;
                let dataY;
                // Follow what the marks drew, not what the layout resolved to — an inferred stack the
                // marks declined would put the point somewhere nothing is drawn
                if (this.ctx.isStacked) {
                    const matchingData = this.ctx.flatData.find((d) => this.x(d) === this.xValue);
                    const stackValue = matchingData
                        ? this.ctx.series.getStackValue(seriesInfo.key, matchingData)
                        : null;
                    const stackedY1 = stackValue
                        ? this.ctx.series.stackLayout === 'stackDiverging' && stackValue[1] <= 0
                            ? stackValue[0]
                            : stackValue[1]
                        : 0;
                    if (this.ctx.valueAxis === 'x') {
                        pointX = this.ctx.xScale(stackedY1) + this.xOffset;
                        pointY = this.yCoordScalar + this.yOffset;
                        dataX = stackedY1;
                        dataY = this.yValue;
                    }
                    else {
                        pointX = this.xCoordScalar + this.xOffset;
                        pointY = this.ctx.yScale(stackedY1) + this.yOffset;
                        dataX = this.xValue;
                        dataY = stackedY1;
                    }
                }
                else {
                    const seriesValue = seriesInfo.value;
                    if (seriesValue == null) {
                        return [];
                    }
                    if (Array.isArray(seriesValue)) {
                        if (this.ctx.valueAxis === 'x') {
                            return seriesValue.map((sv) => ({
                                x: this.ctx.xScale(sv) + this.xOffset,
                                y: this.yCoordScalar + this.yOffset,
                                fill: this.#pointFill(seriesInfo),
                                data: { x: sv, y: this.yValue },
                                seriesKey: seriesInfo.key,
                            }));
                        }
                        else {
                            return seriesValue.map((sv) => ({
                                x: this.xCoordScalar + this.xOffset,
                                y: this.ctx.yScale(sv) + this.yOffset,
                                fill: this.#pointFill(seriesInfo),
                                data: { x: this.xValue, y: sv },
                                seriesKey: seriesInfo.key,
                            }));
                        }
                    }
                    if (this.ctx.valueAxis === 'x') {
                        pointX = this.ctx.xScale(seriesValue) + this.xOffset;
                        pointY = this.yCoordScalar + this.yOffset;
                        dataX = seriesValue;
                        dataY = this.yValue;
                    }
                    else {
                        pointX = this.xCoordScalar + this.xOffset;
                        pointY = this.ctx.yScale(seriesValue) + this.yOffset;
                        dataX = this.xValue;
                        dataY = seriesValue;
                    }
                }
                return {
                    x: pointX,
                    y: pointY,
                    fill: this.#pointFill(seriesInfo),
                    data: { x: dataX, y: dataY },
                    seriesKey: seriesInfo.key,
                };
            })
                .filter(notNull);
        }
        else if (Array.isArray(this.xCoord)) {
            if (Array.isArray(this.highlightData)) {
                const highlightSeriesPoint = this.highlightData;
                if (Array.isArray(this.ctx.data)) {
                    const seriesPointsData = this.ctx.data
                        .map((series) => ({
                        series,
                        point: series.find((d) => this.y(d) === this.y(highlightSeriesPoint)),
                    }))
                        .filter((d) => d.point);
                    tmpPoints = seriesPointsData
                        .map((seriesPoint) => {
                        const fill = this.ctx.cChannel ? this.ctx.cGet(seriesPoint.series) : null;
                        return {
                            x: this.ctx.xScale(seriesPoint.point[1]) + this.xOffset,
                            y: this.yCoordScalar + this.yOffset,
                            fill,
                            data: { x: seriesPoint.point[1], y: this.yValue },
                            seriesKey: undefined,
                        };
                    })
                        .filter(notNull);
                }
            }
            else {
                tmpPoints = this.xCoord
                    .map((xItem, i) => {
                    if (xItem == null)
                        return null;
                    // @ts-expect-error - TODO: fix type
                    const _key = this.ctx.config.x?.[i];
                    const fill = this.ctx.cChannel
                        ? this.ctx.cGet({ ...this.highlightData, $key: _key })
                        : null;
                    return {
                        x: xItem + this.xOffset,
                        y: this.yCoordScalar + this.yOffset,
                        fill,
                        data: { x: this.xValue, y: this.yValue },
                        seriesKey: _key,
                    };
                })
                    .filter(notNull);
            }
        }
        else if (Array.isArray(this.yCoord)) {
            if (Array.isArray(this.highlightData)) {
                const highlightSeriesPoint = this.highlightData;
                if (Array.isArray(this.ctx.data)) {
                    const seriesPointsData = this.ctx.data
                        .map((series) => ({
                        series,
                        point: series.find((d) => this.x(d) === this.x(highlightSeriesPoint)),
                    }))
                        .filter((d) => d.point);
                    tmpPoints = seriesPointsData
                        .map((seriesPoint) => {
                        const fill = this.ctx.cChannel ? this.ctx.cGet(seriesPoint.series) : null;
                        return {
                            x: this.xCoord + this.xOffset,
                            y: this.ctx.yScale(seriesPoint.point[1]) + this.yOffset,
                            fill,
                            data: { x: this.xValue, y: seriesPoint.point[1] },
                            seriesKey: undefined,
                        };
                    })
                        .filter(notNull);
                }
            }
            else {
                tmpPoints = this.yCoord
                    .map((yItem, i) => {
                    if (yItem == null)
                        return null;
                    // @ts-expect-error - TODO: fix type
                    const _key = this.ctx.config.y[i];
                    const fill = this.ctx.cChannel
                        ? this.ctx.cGet({ ...this.highlightData, $key: _key })
                        : null;
                    return {
                        x: this.xCoord + this.xOffset,
                        y: yItem + this.yOffset,
                        fill,
                        data: { x: this.xValue, y: this.yValue },
                        seriesKey: _key,
                    };
                })
                    .filter(notNull);
            }
        }
        else if (this.xCoord != null && this.yCoord != null) {
            const fill = this.ctx.cChannel ? this.ctx.cGet(this.highlightData) : null;
            tmpPoints = [
                {
                    x: this.xCoord + this.xOffset,
                    y: this.yCoord + this.yOffset,
                    fill: fill,
                    data: { x: this.xValue, y: this.yValue },
                    seriesKey: undefined,
                },
            ];
        }
        else {
            tmpPoints = [];
        }
        if (this.ctx.radial) {
            tmpPoints = tmpPoints.map((p) => {
                const [x, y] = pointRadial(p.x, p.y);
                return { ...p, x, y };
            });
        }
        if (props.r) {
            const pointR = this.getPointRadius(this.highlightData);
            if (pointR != null) {
                tmpPoints = tmpPoints.map((p) => ({ ...p, r: pointR }));
            }
        }
        return tmpPoints;
    });
}
